          "$ref": "#/$defs/Id"
        },
        "desktopId": {
          "$ref": "#/$defs/Id"
        },
        "phase": {
          "enum": [
            "queued",
            "running",
            "waiting_approval",
            "waiting_input",
            "stopping",
            "ended"
          ]
        },
        "outcome": {
          "enum": [
            "success",
            "failed",
            "cancelled",
            "unknown",
            null
          ]
        },
        "quiescence": {
          "enum": [
            "not_confirmed",
            "pending",
            "confirmed"
          ]
        },
        "closingReason": {
          "type": [
            "string",
            "null"
          ]
        },
        "revision": {
          "type": "integer",
          "minimum": 1
        },
        "createdAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "endedAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "receipts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Id"
          }
        },
        "unknownActions": {
          "type": "integer",
          "minimum": 0
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "phase": {
                "const": "ended"
              }
            }
          },
          "then": {
            "properties": {
              "quiescence": {
                "const": "confirmed"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "ownership": {
                "const": "external_client"
              }
            }
          },
          "then": {
            "properties": {
              "lifetime": {
                "const": "connection_scoped"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "ownership": {
                "const": "platform"
              }
            }
          },
          "then": {
            "properties": {
              "lifetime": {
                "const": "platform_durable"
              }
            }
          }
        }
      ]
    },
